Mesh<Point, double> mesh;
for (auto fit = rt.finite_facets_begin(); fit != rt.finite_facets_end(); ++fit) {
    if (!is_large_facet(rt, *fit, threshold)) continue;

    RT::Cell_handle c1 = fit->first;
    int k = fit->second;
    RT::Cell_handle c2 = c1->neighbor(k);

    if (rt.is_infinite(c1) || rt.is_infinite(c2)) continue;

    auto seg = rt.dual(*fit);               // CGAL returns a Segment_3
    mesh.add_edge(seg.source(), seg.target());
}
return mesh;

